// CERT KUMITE fighters, built from src/kumite/manifest.json (generated by tools/kumite_assets.py).
import manifest from './manifest.json'

export interface Fighter { id: string; num: number; name: string; color: string; foot: [number, number]; height: number }
export const KM = manifest as unknown as {
  poses: string[]
  cell: [number, number]
  fighters: Fighter[]
  portrait: number
  fx: { cell: [number, number]; names: string[] }
  platform: { size: [number, number]; top: number }
  floor: number
}
export const FIGHTERS: Fighter[] = KM.fighters
export const fighterById = (id?: string): Fighter => FIGHTERS.find((f) => f.id === id) ?? FIGHTERS[0]
export const isFighter = (id: unknown): id is string => typeof id === 'string' && FIGHTERS.some((f) => f.id === id)
export const POSE = Object.fromEntries(KM.poses.map((p, i) => [p, i])) as Record<'idle1' | 'idle2' | 'walk1' | 'walk2' | 'quick' | 'strong' | 'special' | 'air' | 'hurt' | 'ko' | 'win', number>
export const FX = Object.fromEntries(KM.fx.names.map((p, i) => [p, i])) as Record<'spark' | 'bigspark' | 'clash' | 'dust' | 'dizzy' | 'flame' | 'fall' | 'win', number>

const BASE = import.meta.env.BASE_URL + 'kumite/'
export const asset = (file: string) => BASE + file

const cache = new Map<string, Promise<HTMLImageElement>>()
export function loadImage(file: string): Promise<HTMLImageElement> {
  let p = cache.get(file)
  if (!p) {
    p = new Promise((res, rej) => { const im = new Image(); im.decoding = 'async'; im.onload = () => res(im); im.onerror = rej; im.src = asset(file) })
    cache.set(file, p)
  }
  return p
}
/** Portrait strip holds 10 squares ordered by fighter number (01–10). */
export const portraitIndex = (f: Fighter) => f.num - 1
